from collections import defaultdict

def solve():
    n, p, M, m = map(int, input().split())
    complaints = [list(map(int, input().split())) for _ in range(n)]
    stations = [list(map(int, input().split())) for _ in range(p)]
    conflicting_pairs = [list(map(int, input().split())) for _ in range(m)]

    def is_satisfiable(coverage, interference_map):
        stations_within_range = set(station for station, l, r in stations if l <= coverage <= r)
        if not stations_within_range:
            return False

        conflicting = False
        for u, v in interfering_map:
            if (u in stations_within_range and v in stations_within_range) or (
                    u not in stations_within_range and v not in stations_within_range):
                conflicting = True
        return not conflicting

    for x in range(1, M+1):
        for y in range(x+1, M+1):
            interfering_pairs = []
            conflicting_connections = set()
            for i, (station_x, station_y) in enumerate(complaints):
                if station_x == station_y or (station_x > station_y and station_x <= x or station_x >= y) or \
                   (station_y > station_x and station_y <= x or station_y >= y):
                    if any(station_y in conflicting_connections or station_x in conflicting_connections for station_x, station_y in conflicting_pairs):
                        conflicting_connections.add(station_x)
                        conflicting_connections.add(station_y)
                        interfering_pairs.append((i, station_x, station_y))

            if not conflicting_connections:
                if is_satisfiable(x, conflicting_pairs):
                    return f"{len(conflicting_pairs)} {x}"

    return "-1"

