from collections import deque

def is_winding(s, points):
    offset = 1
    n = len(s)
    for i in range(n):
        a1 = points[i]
        a2 = points[ (i + offset) % n ]
        a3 = points[ (i + 2 * offset) % n ]
        if s[i] == 'R':
            offset -= 1
        elif s[i] == 'L':
            offset += 1
        if s[i] != s[(i + 1) % n]:
            return False
        if (a1[0] * a2[0] + a1[1] * a2[1]) * offset > (a2[0] * a3[0] + a2[1] * a3[1]):
