    prefix_sum_x = set(sum(points[offset:]) for offset in range(n))
    prefix_sum_y = {-sum(points[offset:]) for offset in range(n)}
    s_reverse = s.translate(str.maketrans("LR", "RL"))
    windable = [-1] * n
    for i in range(n):
        l_ind = i
        r_ind = (i + n + offset) % n
        while True:
            left_enc = (points[r_ind] - points[l_ind]).normalize()
            right_enc = s_reverse[l_ind].normalize()
            if (left_enc - right_enc).dot_product(1.0 / windable[l_ind]) > 0:
