import sys

def is_free(z, radius):
    """Check if constructing the sphere of radius at latitude z is free."""
    return z >= radius

def calculate_energy(z, radius, n, nmeans):
    """Calculate the minimum energy cost given latitude and radius."""
    energy = 0
    nmeans.append(0)
    for i in range(n):
        if is_free(z, radius):
            energy += radius**2
        else:
            energy += nmeans[i]
            nmeans[n-1], nmeans[i], nmeans[i] = nmeans[i], nmeans[n-1], nmeans[n-1] - radius**2
    return energy

def solve(n, levels, points, planes, nmeans):
    """Solve the problem and return the energy values for each level."""
    distances = [0] * (n-1)
    nmeans = [x**2 for x in points]
    for level in range(len(planes)):
        n = len(nmeans)
        sphere_points = [level] * n
        for zindex in range(n):
            if nmeans[zindex] != 0:
                distances[zindex] = abs(planes[level][0] * points[zindex][0] + planes[level][1] * points[zindex][1] + planes[level][2] * points[zindex][2]) / planes[level][2]
        minimum_energy = float('inf')
        for r in range(n-1):
            sphere_points[r] = distances[r]
            if r + 1 < n:
                sphere_points[r+1] = distances[n-1]
            minimum_energy = min(minimum_energy, calculate_energy(-sphere_points[r], r+1, n, nmeans))
            for i in range(r+1, n):
                sphere_points[i] = distances[i]
            for i in range(n-1):
                sphere_points[i] = distances[n-1-i]
        minimum_energy /= 2
        levels[level] = minimum_energy

