import bisect

def build_convex_hull(points):
    points.sort()
    hull = []
    for point in points:
        while len(hull) > 1 and crosspoint(hull[-2], hull[-1], point) <= crosspoint(hull[-2], hull[-1], points[-1]):
            del hull[-1]
        hull.append(point)
    return hull

def crosspoint(p1, p2, q1, q2):
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = q1
    x4, y4 = q2
    denominator = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1)
    if denominator == 0:
        return 1e9  # Infinitive length
    biq = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / denominator
    biq = bisect.bisect_right([b,q] for b,q in zip(points, hull) if b[0] <= x1 and x1 <= q[0] and b[1] <= y1 and y1 <= q[1])
    return qup(biq, points, q1), biq

def qup(idx, hull, point):
