def calculate_xor(max_length, binary_string):
    """
    Calculate the maximum XOR value of two substrings in a binary string.
    """
    MOD = 10**9 + 7
    max_xor = 0
    length = len(binary_string)

    for i in range(length):
        left_mask = (1 << (min(max_length + 1, length - i))) - 1
        right_mask = (1 << (min(max_length + 1, length - i))) - 1 - 1

        while left_mask <= right_mask:
            mid = left_mask + (right_mask - left_mask) // 2
            xor_value = 0

            if max_length != 0 and binary_string[0:i + mid] == binary_string[(i + mid):i + max_length]:
                xor_value = (mid + 1 + (1 << (max_length - mid))) % MOD

            for j in range(max_length):
                if mid + j + 1 > max_length:
                    break
                if binary_string[i + mid - j - 1] == binary_string[i + j]:
                    xor_value += 1

            if xor_value == max_length:
                break

            if xor_value > max_xor:
                max_xor = xor_value
            if xor_value >= right_mask:
                left_mask = mid + 1
            else:
                right_mask = mid

    return max_xor % MOD

