import sys

def rucksack(weights, values):
    weights.sort(reverse=True)
    values.sort(reverse=True)
    total_val = sum(values)
    available_cap = 0
    path_vals = []

    for i, weight in enumerate(weights):
        if (total_val - available_cap) < weight:
            break
        n = len(weights) - i - 1
        available_cap += weight
        if n >= 2:
            path_vals.append(available_cap // weight)
            available_cap -= path_vals[-1]
        elif n == 1:
            path_vals.append(available_cap // weight)

    return path_vals

def distribute_road_roads(map):
    n = len(map)
    path_mat = [[0 for _ in range(n)] for _ in range(n)]
    dist = [[0 for _ in range(n)] for _ in range(n)]

    for x, y in map:
        path_mat[x-1][y-1] = path_mat[y-1][x-1] = 1
        dist[x-1][y-1] = dist[y-1][x-1] = 1
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > 0:
                    if dist[i][k] and dist[k][j] and path_mat[i][k] and path_mat[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    matching = [[0 for _ in range(n)] for _ in range(n)]
    match, unmatched = 0, n

    for i in range(n):
        for j in range(n):
            if dist[i][j] != 0 and i != j:
                matching[i - 1][j - 1] = max(1, match // dist[i][j])
                unmatched -= matching[i - 1][j - 1]
                match += matching[i - 1][j - 1]

    r = match
    return r

def solve(num_roads):
    n = num_roads + 1
    total_roads = 0
    map = []
    prices = []
    companies = [i for i in range(1, 10001)]
    cost = [0 for _ in range(10001)]
    sum_company_branching = [0 for _ in range(10001)]

    for i in range(num_roads):
        a, b = map[i * 2 - 1], map[i * 2]
        maps = []
        maps.append((a - 1, b - 1))
        maps.append((b - 1, a - 1))
        map.append(maps)
        total_roads += 1

    for i in range(total_roads):
        c = cost[companies[i]]
        company_branching = max(1, sum_company_branching[i] // c)
        sum_company_branching[i] += company_branching

    while cost[companies[-1]] > 0:
        next_company = max(companies, key=lambda x: cost[x])
        pair = map[companies.index(next_company)]
        total_roads += 1

        for i in range(-1, -total_roads - 1, -1):
            a, b = (pair[0] if i == -total_roads else companies[i]), (pair[1] if i == -total_roads else companies[i])
            if sum_company_branching[a] == sum_company_branching[b]:
                if ((sum_company_branching[a] - company_branching) == cost[companies[i]]):
                    for x, y in map[companies.index(next_company)]:
                        cost[companies[x]] -= company_branching
                        cost[companies[y]] -= company_branching
                    companies[companies.index(next_company)] = c
            else:
                if (sum_company_branching[a] + company_branching) <= (sum_company_branching[b] + company_branching):
                    for x, y in map[companies.index(next_company)]:
                        cost[companies[x]] -= company_branching
                        cost[companies[y]] -= company_branching
                    companies[companies.index(next_company)] = c
            sum_company_branching[a] = sum_company_branching[b] - company_branching

        cost[next_company] -= company_branching

        next_compare = max(companies, key=lambda x: cost[x])
        if cost[next_compare] > cost[next_company]:  
            next_company = next_compare

    c = rucksack([company_branching for company_branching in cost], r)

    return ",".join(str(i) for i in range(num_roads)) + "\n" + "\n".join(str(int(i)) for i in c)
