class SmallestHeap():

    def __init__(self, n: int):
        self.max_heap: List[Tuple[int, int]] = [(-1, 0)] * n

    def get_min_index(self) -> int:
        if len(self.max_heap) == 1 : 
            return self.max_heap[0][1]
        while len(self.max_heap) >= 2:
            cur: int = self.get_top() or 0
            if cur == 0: return self.get_top()
            x, p = self.max_heap.pop()
            self.add_to_heap(p, x)
        p, _ = self.max_heap.pop()
        return p

    def peek(self, q=1) -> Tuple[int, int]:
        cur: int = self.get_top() or 0
        if cur == 0: return self.max_heap[q+1][1], self.max_heap[q+1][0]
        x, p = self.max_heap.pop()
        if x == cur:
            return self.max_heap[q+1][1], self.max_heap[q+1][0]
        self.add_to_heap(p, x)
        return self.peek(q+1)

    def add_to_heap(self, worth: int, minimal_index: int):
        while len(self.max_heap) >= 2:
            top: int, _ = self.max_heap[0]
            top_worth: int, _ = self.max_heap[1]
            if worth - top_worth + top >= top_worth:
                if minimal_index >= top: return
                self.add_after(top, minimal_index)
                return
            x, p = self.max_heap.pop()
            self.add_to_heap(worth, x)
            self.add_to_heap(worth * 2, x)
            self.add_to_heap(worth * 2, minimal_index)
            break

    def add_after(self, prev: int, should_be):
        replaced = len(self.max_heap)
        self.max_heap.insert(0, (prev, should_be))
        while (len(self.max_heap) > 0) and not (len(self.max_heap) % 2 == 1):
            top: int, _ = self.max_heap.pop()
            x, p = self.max_heap.pop()
            self.add_to_heap(top, p)
            self.add_to_heap(x, should_be)
        return replaced

    def get_top(self) -> Tuple[int, int]:
        if len(self.max_heap) < 1:
            return None
        _top: int, __ = self.max_heap[0]
        return _top, __

class CreatureHeap():
    def __init__(self, k: int):
        assert(k <= 12)
        self.trials: SmallestHeap = SmallestHeap(k)
        self.k: int = k

    def add(self, *creatures) -> None:
        for x in creatures:
            prev_minimal_index: int = self.trials.get_min_index()
            x: int = x[-1]
            if x <= prev_minimal_index: continue
            minimal_index: int = x
            for i in range(self.k):
                if x > self.trials.max_heap[i][1]:
                    minimal_index = i
            self.trials.add(minimal_index, x)
            self.trials.add_to_heap(x, minimal_index)

