def optimal_range_selection(v: List[int], c: List[int], li: int, k: int) -> tuple:
    """
    Select an (li, ri) such that the minimum value of max(v, c)
    over all ranges [li, ri] is maximized.
    """
    ri_min = max(li, li + k - 1) - 1
    if ri_min >= len(v):
        ri_min = len(v) - 1
    best_li = ri_min
    best_visitors, best_revenue = v[ri_min], c[ri_min]

    to_check = [ri_min]
    while to_check:
        r = to_check.pop()
        if r == len(v) - 1:
            return tuple(best_li, best_revenue)
        if r < len(v) - 1 and c[r + 1] < best_revenue:
            to_check.append(r + 1)
        to_check.append(r + 1)
        to_check.append(r)
        if c[r] < best_revenue:
            to_check.append(r)
        if v[r] > best_visitors and c[r] > best_revenue:
            best_revenue, best_visitors = v[r], c[r]
            best_li = r
    return tuple(best_li, best_revenue)

def calculate_expected_grade(v: List[int], c: List[int], n: int, k: int):
    total_sum = 0
    for li in range(n + 1):
        ri = min(li + k - 1, n)
        best_range = optimal_range_selection(v, c, li, ri)
        total_sum += min(best_range[1] * 100, 5000000)
    return total_sum / (k * (n - li + 1))

