def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_platform(platforms, a, h):
    # Reduce platforms and h to manageable size
    while a % 2 == 0:
        a //= 2
    while a % 5 == 0:
        a //= 5
    platforms = [h1 % a for h1 in platforms]
    h -= h
    # Simulate jumping from 0 to the highest platform
    for i in range(h, a, h):
        for j in range(2, a // i + 1):
            if is_prime(i + j) and i < a:
                platforms[i] = 0
                break

    # Check if any reach line platform
    for i in platforms:
        if i >= a:
            return "YES"
    return "NO"

