from collections import defaultdict

def c(l, r):
    return sum(math.gcd(i, j) >= l and c(gcd(i, r), gcd(j, r)) if gcd(i, j) >= l else 0 for i in range(l, r+1) for j in range(i, r+1))

def compute_f(n, k):
    dp = defaultdict(int)
    sequence = [0]
    for i in range(1, n+1):
        g = c(i, n)
        if g != math.inf:
            dp[g] = i
        while sequence[-1] < i:
            if len(sequence) > k:
                dig_g = c(sequence[-1], sequence[-2])
                dp[dig_g] = max(dp[dig_g], c(sequence[-1]-1, i-1))
                if dig_g < math.inf and i-dig_g != math.inf:
                    dp[dig_g] = max(dp[dig_g], c(sequence[-1]-1, dig_g))
            sequence.append(i)
    return sum(dp[g] <= (n - g) for g in dp)

