            left_value = 0
            for i in range(1, len(self.history)):
                one_or_both = self.history[i] + self.history[i-1] + probability
                if one_or_both > self.history[i]:
                    if i % 1000 == 0:
                        print(self.history)
                    left_value = 1
                    break
                right_value = 1 - self.walk(i, 1 - probability)
                self.history[i] = max(self.history[i-1] + probability, self.history[i] + probability, self.history[i] + probability * one_or_both)

            if left_value == 1:
                return

            right_value = 1 - self.walk(len(self.history) - 1, 1 - probability)
            self.history[-1] = max(self.history[-1] + probability, self.history[-1] + probability * probability)

            max_prob_left = self.history[1]
            for i in range(2, len(self.history)):
                max_prob_left = max(self.history[i] + probability, max_prob_left)
                if max_prob_left >= right_value:
