        high = [pt[1] for pt in points]
        self.p = (0, max(high))

        eps = 0.00001
        while True:
            m, i1, j1 = self._quickhull(points)
            m, i2, j2 = self._quickhull(points)
            if i2 - i1 == 1:
                # Already good
                break
            elif j2 - j1 == 1:
                i1, j1 = j2, i2
            else:
                break

        replace = self.hull
        self.hull = []
        for i, j in range(i1 + 1, j1 + 1):
            # Branch without points at i and j...
            self.hull.append(points[i])
            points[i], points[j] = points[j], points[i]
            points.pop()
            points.pop()

        m, i, j = self._quickhull(points)
        if m == 1:
            for p in points:
                self.hull.append(self.cutout(points, p))
        else:
            for pi in replace:
                self.hull.append(pi)

    def cutout(self, points, p):
        # Cutout algorithm - quick and dirty
        m, i, j = self._quickhull(points)
        if not m:
            # Points behind pivot point do not intersect convex hull.
            # We assume we are facing the open way, hence that i is greater than one
