To solve this problem, we will use a combination of a Segment Tree and a Fenwick Tree. The Segment Tree will be used to answer the range sum queries, while the Fenwick Tree (also known as a Binary Indexed Tree) will be used to efficiently update the array values and answer the range queries.

Here's a Python program that addresses the given problem:

```python
# Function to perform range sum query with appropriate coefficients
def range_sum_with_coeffs(tree, n, l, r, coeff):
    res = 0
    x = 1
    for i in range(n - 1, -1, -1):
        high = (coeff & 1)
        if l & x > 0:
            res += tree[i]
        if r & x > 0:
            res -= tree[i]
        high <<= 1
        coeff >>= 1
    return res

# Function to update the array with appropriate coefficients
def update_array_with_coeffs(arr, n, coeff):
    coeff ^= 1
    x = 2 ** 30
    arr[n - 1] ^= coeff
    for i in range(n - 2, -1, -1):
        arr[i] = (arr[i] + 1) ^ (coeff & 1) ^ (arr[i + 1] << 1)
        coeff >>= 1
    return arr

# Function to preprocess the Segment Tree with appropriate coefficients
def preprocess_segment_tree(tree, n, a, queries, index, coeff):
    for l, r, x, y in queries:
        if y in a:
            tree[index] = y
        else:
            coeff ^= 1
    start = n - len(a)
    key = 0
    for i in range(len(a) - 1, -1, -1):
        nbit = offset(key):
        lowbit := highbit & ~l;
        x = highbit + highbit >> 1;
        if l & highbit > 0:
            tree[nbit] += x;
        mid = key + n;
        highbit, lowbit = (tree[mid] >> 1) + 1, highbit - x;
        key = mid
    return tree

# Function to implement GukiZiana function
def gukiZiana(a, y, tree, index, mqueries, coeff):
    if y not in a:
        return -1
    temp = range_sum_with_coeffs(tree, mqueries[0][0], y, y, 0);
    R = fixup(highbit);
    return (temp - apply) * R;
